# M0-019 regression now uses only canonical durable models. Custom subclasses that
# impersonate a frozen canonical ObjectType are intentionally rejected after B10.
Path("tests/unit/test_reference_validation_m019.py").write_text('''"""M0-019 reference existence and same-transaction validation tests."""\nfrom __future__ import annotations\n\nfrom datetime import datetime, timezone\n\nimport pytest\n\nfrom aios_core.contracts import (\n    EvidenceCoverage,\n    EvidenceSet,\n    KnowledgeWindow,\n    ObjectRef,\n    ObjectType,\n    Observation,\n    OperationRequest,\n    Relation,\n    SourceRef,\n    TemporalExtent,\n    new_object_id,\n)\nfrom aios_core.contracts.enums import ErrorCode\nfrom aios_core.storage import SQLiteWorldStore, StoreError\n\nNOW = datetime(2026, 9, 14, 6, 0, tzinfo=timezone.utc)\n\n\ndef op(expected: int, key: str) -> OperationRequest:\n    return OperationRequest(\n        operation_name="world.commit",\n        expected_world_revision=expected,\n        reason="M0-019 reference validation",\n        idempotency_key=key,\n    )\n\n\ndef obs(\n    object_id: str,\n    revision: int = 1,\n    *,\n    learned_at: datetime = NOW,\n    source_refs: list[SourceRef] | None = None,\n) -> Observation:\n    return Observation(\n        object_id=object_id,\n        subject_id="user_1",\n        revision=revision,\n        occurred=TemporalExtent.point(learned_at),\n        learned_at=learned_at,\n        recorded_at=learned_at,\n        source_refs=source_refs or [],\n        created_by="m0-019-test",\n        source_kind="chat",\n        modality="text",\n        value="raw evidence",\n    )\n\n\ndef relation(\n    object_id: str,\n    left: ObjectRef,\n    right: ObjectRef,\n    *,\n    revision: int = 1,\n    learned_at: datetime = NOW,\n) -> Relation:\n    return Relation(\n        object_id=object_id,\n        subject_id="user_1",\n        revision=revision,\n        occurred=TemporalExtent.point(learned_at),\n        learned_at=learned_at,\n        recorded_at=learned_at,\n        created_by="m0-019-test",\n        left=left,\n        relation_type="linked",\n        right=right,\n        confidence=0.5,\n    )\n\n\ndef test_m019_01_missing_object_ref_rejected_without_partial_commit(tmp_path):\n    store = SQLiteWorldStore(tmp_path / "world.db")\n    holder = relation(\n        new_object_id(ObjectType.RELATION),\n        ObjectRef(object_id="missing-a", revision=1),\n        ObjectRef(object_id="missing-b", revision=1),\n    )\n\n    with pytest.raises(StoreError) as exc:\n        store.commit([holder], op(0, "missing-ref"))\n\n    assert exc.value.code == ErrorCode.NOT_FOUND\n    assert store.current_world_revision() == 0\n    assert store.list_payloads() == []\n\n\ndef test_m019_02_same_transaction_evidence_set_can_reference_new_observation(tmp_path):\n    store = SQLiteWorldStore(tmp_path / "world.db")\n    observation_id = new_object_id(ObjectType.OBSERVATION)\n    evidence_id = new_object_id(ObjectType.EVIDENCE_SET)\n    observation = obs(observation_id)\n    evidence = EvidenceSet(\n        object_id=evidence_id,\n        subject_id="user_1",\n        revision=1,\n        learned_at=NOW,\n        recorded_at=NOW,\n        created_by="m0-019-test",\n        purpose="support claim",\n        knowledge_window=KnowledgeWindow(knowledge_cutoff=NOW, world_revision=0),\n        member_refs=[ObjectRef(object_id=observation_id, revision=1)],\n        support_refs=[ObjectRef(object_id=observation_id, revision=1)],\n        selection_method="explicit",\n        coverage=EvidenceCoverage(expected_count=1, observed_count=1, coverage_ratio=1.0),\n    )\n\n    result = store.commit([observation, evidence], op(0, "same-tx-evidence"))\n\n    assert result.world_revision == 1\n    assert store.get_payload(evidence_id)["member_refs"][0] == {\n        "object_id": observation_id,\n        "revision": 1,\n    }\n\n\ndef test_m019_03_same_transaction_mutual_non_evidence_refs_remain_legal(tmp_path):\n    store = SQLiteWorldStore(tmp_path / "world.db")\n    a_id = new_object_id(ObjectType.RELATION)\n    b_id = new_object_id(ObjectType.RELATION)\n    a = relation(\n        a_id,\n        ObjectRef(object_id=b_id, revision=1),\n        ObjectRef(object_id=b_id, revision=1),\n    )\n    b = relation(\n        b_id,\n        ObjectRef(object_id=a_id, revision=1),\n        ObjectRef(object_id=a_id, revision=1),\n    )\n\n    result = store.commit([a, b], op(0, "mutual-links"))\n    assert result.world_revision == 1\n\n\ndef test_m019_04_current_revision_objectref_self_reference_rejected(tmp_path):\n    store = SQLiteWorldStore(tmp_path / "world.db")\n    object_id = new_object_id(ObjectType.RELATION)\n    holder = relation(\n        object_id,\n        ObjectRef(object_id=object_id, revision=1),\n        ObjectRef(object_id=object_id, revision=1),\n    )\n\n    with pytest.raises(StoreError) as exc:\n        store.commit([holder], op(0, "self-object-ref"))\n    assert exc.value.code == ErrorCode.DEPENDENCY_INVALID\n    assert store.current_world_revision() == 0\n\n\ndef test_m019_05_current_revision_sourceref_self_reference_rejected(tmp_path):\n    store = SQLiteWorldStore(tmp_path / "world.db")\n    object_id = new_object_id(ObjectType.OBSERVATION)\n    holder = obs(\n        object_id,\n        source_refs=[SourceRef(object_id=object_id, revision=1)],\n    )\n\n    with pytest.raises(StoreError) as exc:\n        store.commit([holder], op(0, "self-source-ref"))\n    assert exc.value.code == ErrorCode.DEPENDENCY_INVALID\n    assert store.current_world_revision() == 0\n\n\ndef test_m019_06_previous_revision_self_link_is_historical_and_legal(tmp_path):\n    store = SQLiteWorldStore(tmp_path / "world.db")\n    endpoint_id = new_object_id(ObjectType.OBSERVATION)\n    relation_id = new_object_id(ObjectType.RELATION)\n    endpoint = obs(endpoint_id)\n    first = relation(\n        relation_id,\n        ObjectRef(object_id=endpoint_id, revision=1),\n        ObjectRef(object_id=endpoint_id, revision=1),\n    )\n    store.commit([endpoint, first], op(0, "self-history-v1"))\n\n    second = relation(\n        relation_id,\n        ObjectRef(object_id=relation_id, revision=1),\n        ObjectRef(object_id=endpoint_id, revision=1),\n        revision=2,\n    )\n    result = store.commit([second], op(1, "self-history-v2"))\n    assert result.world_revision == 2\n\n\ndef test_m019_07_commit_has_no_public_reference_validation_bypass(tmp_path):\n    store = SQLiteWorldStore(tmp_path / "world.db")\n    holder = relation(\n        new_object_id(ObjectType.RELATION),\n        ObjectRef(object_id="missing-a", revision=1),\n        ObjectRef(object_id="missing-b", revision=1),\n    )\n\n    with pytest.raises(TypeError):\n        store.commit([holder], op(0, "no-bypass"), validate_references=False)  # type: ignore[call-arg]\n    assert store.current_world_revision() == 0\n\n\ndef test_m019_08_pending_future_reference_rejected_by_knowledge_cutoff(tmp_path):\n    store = SQLiteWorldStore(tmp_path / "world.db")\n    older = datetime(2026, 9, 14, 5, 0, tzinfo=timezone.utc)\n    newer = datetime(2026, 9, 14, 6, 0, tzinfo=timezone.utc)\n    target_id = new_object_id(ObjectType.OBSERVATION)\n    holder = relation(\n        new_object_id(ObjectType.RELATION),\n        ObjectRef(object_id=target_id, revision=1),\n        ObjectRef(object_id=target_id, revision=1),\n        learned_at=older,\n    )\n    target = obs(target_id, learned_at=newer)\n\n    with pytest.raises(StoreError) as exc:\n        store.commit([holder, target], op(0, "future-pending"))\n    assert exc.value.code == ErrorCode.NOT_FOUND\n    assert exc.value.context["reason"] == "reference_not_visible_or_missing"\n    assert store.current_world_revision() == 0\n''', encoding="utf-8")

# New B10/B11 adversarial regressions.
Path("tests/unit/test_m0_gate_fifth_followup.py").write_text('''from __future__ import annotations\n\nimport json\nimport sqlite3\nfrom datetime import datetime, timezone\n\nimport pytest\n\nfrom aios_core.contracts import (\n    Dependency,\n    ObjectRef,\n    ObjectType,\n    Observation,\n    OperationRequest,\n    TemporalExtent,\n    WorldObject,\n    new_object_id,\n)\nfrom aios_core.contracts.enums import ErrorCode\nfrom aios_core.storage import SQLiteWorldStore, StoreError\n\nNOW = datetime(2026, 9, 14, 11, 0, tzinfo=timezone.utc)\n\n\ndef op(expected: int, key: str) -> OperationRequest:\n    return OperationRequest(\n        operation_id=f"op-{key}",\n        session_id="m0-fifth-followup",\n        operation_name="world.commit",\n        arguments={"gate": "B10-B11"},\n        expected_world_revision=expected,\n        reason="M0 Gate B10/B11 follow-up",\n        idempotency_key=key,\n    )\n\n\ndef obs(object_id: str, value) -> Observation:\n    return Observation(\n        object_id=object_id,\n        subject_id="gate-user",\n        revision=1,\n        occurred=TemporalExtent.point(NOW),\n        learned_at=NOW,\n        recorded_at=NOW,\n        created_by="m0-gate-fifth-followup",\n        source_kind="test",\n        modality="json",\n        value=value,\n    )\n\n\ndef fake(object_type: ObjectType) -> WorldObject:\n    return WorldObject(\n        object_id=f"fake-{object_type.value}",\n        object_type=object_type,\n        subject_id="gate-user",\n        revision=1,\n        occurred=TemporalExtent.point(NOW),\n        learned_at=NOW,\n        recorded_at=NOW,\n        created_by="m0-gate-fifth-followup",\n    )\n\n\n@pytest.mark.parametrize(\n    "object_type",\n    [\n        ObjectType.DEPENDENCY,\n        ObjectType.EVIDENCE_SET,\n        ObjectType.TASK,\n        ObjectType.EVENT,\n        ObjectType.CLAIM,\n        ObjectType.RELATION,\n        ObjectType.DIMENSION_DEFINITION,\n    ],\n)\ndef test_b10_base_worldobject_cannot_masquerade_as_canonical_type(tmp_path, object_type):\n    store = SQLiteWorldStore(tmp_path / "world.db")\n    with pytest.raises(StoreError) as exc:\n        store.commit([fake(object_type)], op(0, f"b10-{object_type.value}"))\n    assert exc.value.code is ErrorCode.INVALID_ARGUMENT\n    assert exc.value.context["reason"] == "persistence_revalidation_failed"\n    assert store.current_world_revision() == 0\n    assert store.list_payloads() == []\n\n\ndef test_b10_legacy_poisoned_dependency_row_maps_to_storage_failure(tmp_path):\n    path = tmp_path / "world.db"\n    store = SQLiteWorldStore(path)\n    poison_id = new_object_id(ObjectType.OBSERVATION)\n    a_id = new_object_id(ObjectType.OBSERVATION)\n    b_id = new_object_id(ObjectType.OBSERVATION)\n    store.commit(\n        [obs(poison_id, "poison"), obs(a_id, "a"), obs(b_id, "b")],\n        op(0, "seed-poison"),\n    )\n\n    with sqlite3.connect(path) as conn:\n        row = conn.execute(\n            "SELECT payload_json FROM object_revisions WHERE object_id=? AND revision=1",\n            (poison_id,),\n        ).fetchone()\n        payload = json.loads(row[0])\n        payload["object_type"] = ObjectType.DEPENDENCY.value\n        conn.execute(\n            "UPDATE object_revisions SET object_type=?, payload_json=? WHERE object_id=? AND revision=1",\n            (ObjectType.DEPENDENCY.value, json.dumps(payload), poison_id),\n        )\n        conn.commit()\n\n    dependency = Dependency(\n        object_id=new_object_id(ObjectType.DEPENDENCY),\n        subject_id="gate-user",\n        revision=1,\n        occurred=TemporalExtent.point(NOW),\n        learned_at=NOW,\n        recorded_at=NOW,\n        created_by="m0-gate-fifth-followup",\n        dependent_ref=ObjectRef(object_id=a_id, revision=1),\n        dependency_ref=ObjectRef(object_id=b_id, revision=1),\n        dependency_type="requires",\n    )\n\n    with pytest.raises(StoreError) as exc:\n        store.commit([dependency], op(1, "after-poison"))\n    assert exc.value.code is ErrorCode.STORAGE_FAILURE\n    assert exc.value.context["reason"] == "corrupt_dependency_payload"\n    assert store.current_world_revision() == 1\n\n\ndef test_b11_non_string_mapping_key_is_rejected_without_data_loss(tmp_path):\n    store = SQLiteWorldStore(tmp_path / "world.db")\n    object_id = new_object_id(ObjectType.OBSERVATION)\n    value = {1: "numeric-key", "1": "string-key"}\n\n    with pytest.raises(StoreError) as exc:\n        store.commit([obs(object_id, value)], op(0, "b11-collision"))\n    assert exc.value.code is ErrorCode.INVALID_ARGUMENT\n    assert exc.value.context["reason"] == "durable_json_validation_failed"\n    assert store.current_world_revision() == 0\n    assert store.list_payloads() == []\n\n\ndef test_b11_nested_non_string_mapping_key_is_rejected(tmp_path):\n    store = SQLiteWorldStore(tmp_path / "world.db")\n    object_id = new_object_id(ObjectType.OBSERVATION)\n    with pytest.raises(StoreError) as exc:\n        store.commit([obs(object_id, {"outer": {1: "x"}})], op(0, "b11-nested"))\n    assert exc.value.code is ErrorCode.INVALID_ARGUMENT\n    assert exc.value.context["reason"] == "durable_json_validation_failed"\n    assert store.current_world_revision() == 0\n\n\ndef test_b11_invalid_retry_cannot_alias_existing_idempotency_key(tmp_path):\n    path = tmp_path / "world.db"\n    store = SQLiteWorldStore(path)\n    object_id = new_object_id(ObjectType.OBSERVATION)\n    request = op(0, "b11-retry")\n    store.commit([obs(object_id, {"1": "string-key"})], request)\n\n    altered = obs(object_id, {1: "numeric-key", "1": "string-key"})\n    with pytest.raises(StoreError) as exc:\n        SQLiteWorldStore(path).commit([altered], request)\n    assert exc.value.code is ErrorCode.IDEMPOTENCY_CONFLICT\n    assert exc.value.context["reason"] == "request_revalidation_failed"\n    assert SQLiteWorldStore(path).current_world_revision() == 1\n\n\ndef test_b11_operation_arguments_nested_non_string_key_rejected(tmp_path):\n    store = SQLiteWorldStore(tmp_path / "world.db")\n    request = op(0, "b11-operation")\n    request.arguments["nested"] = {1: "x"}\n    with pytest.raises(StoreError) as exc:\n        store.commit([obs(new_object_id(ObjectType.OBSERVATION), "ok")], request)\n    assert exc.value.code is ErrorCode.INVALID_ARGUMENT\n    assert exc.value.context["reason"] == "durable_json_validation_failed"\n    assert store.current_world_revision() == 0\n\n\ndef test_b11_string_mapping_keys_remain_lossless(tmp_path):\n    store = SQLiteWorldStore(tmp_path / "world.db")\n    object_id = new_object_id(ObjectType.OBSERVATION)\n    value = {"1": "string-key", "nested": {"2": "two"}}\n    result = store.commit([obs(object_id, value)], op(0, "b11-valid"))\n    assert result.world_revision == 1\n    assert store.get_payload(object_id)["value"] == value\n''', encoding="utf-8")

